entries[136968] = { ["name"] = "Storm Dragon Egg", ["text"] = "Quest Item\n\"Lightning crackles over the surface of the shell.\"" }
entries[136969] = { ["name"] = "Tome of Hex: Spider", ["text"] = "Binds when picked up\nClasses: Shaman\nUse: Teaches Hex: Spider.\nTransforms the enemy into a spider for 1 min. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts.\nSell Price:" }
entries[136970] = { ["name"] = "Mask of Mirror Image", ["text"] = "Quest Item\nUse: Copy the appearance of Anarys Lunastre." }
entries[136971] = { ["name"] = "Tome of Hex: Snake", ["text"] = "Binds when picked up\nClasses: Shaman\nUse: Teaches Hex: Snake.\nTransforms the enemy into a snake for 1 min. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts.\nSell Price:" }
entries[136972] = { ["name"] = "Tome of Hex: Cockroach", ["text"] = "Binds when equipped\nClasses: Shaman\nUse: Teaches Hex: Cockroach.\nTransforms the enemy into a cockroach for 1 min. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts.\nSell Price:" }
entries[136973] = { ["name"] = "Burden of Vigilance", ["text"] = "Binds when picked up\nLife Artifact Relic\n+\nSell Price:" }
entries[136974] = { ["name"] = "Empowerment of Thunder", ["text"] = "Binds when picked up\nStorm Artifact Relic\n+\nSell Price:" }
entries[136975] = { ["name"] = "Hunger of the Pack", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 [Agility or Strength]\n+ 7 Critical Strike\nEquip: Increases your Speed by 11 for 10 sec when you kill a target that gives experience or honor.\nSell Price:" }
entries[136976] = { ["name"] = "Etheldrin's Breastplate", ["text"] = "Binds when picked up\nChest Plate\n18 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 3 Haste\n+ 7 Mastery\nDurability 165 / 165\nSell Price:" }
entries[136977] = { ["name"] = "Shadowfeather Shawl", ["text"] = "Binds when picked up\nBack\n3 Armor\n+3 [Agility or Strength or Intellect]\n+4 Stamina\n+ 4 Haste\n+ 2 Versatility\nSell Price:" }
entries[136978] = { ["name"] = "Ember of Nullification", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 [Agility or Strength]\n+ 7 Versatility\nEquip: Taking magic damage has a chance to apply Choking Flames to the attacker, silencing them for 2 sec.\n\nThis may only occur once every 20 sec. (Proc chance: 40%, 20s cooldown)\nSell Price:" }
entries[136979] = { ["name"] = "Shorn Batbrood Cuffs", ["text"] = "Binds when picked up\nWrist Leather\n4 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 4 Critical Strike\n+ 2 Mastery\nDurability 55 / 55\nSell Price:" }
entries[136981] = { ["name"] = "Empyrean Fel Tome", ["text"] = "Quest Item\nUnique (10)\n\"A fel-inscribed tome of demonic spells.\"" }
entries[136983] = { ["name"] = "Grave Dust", ["text"] = "Quest Item\n\"Infused with the sorrows of the departed.\"" }
entries[136984] = { ["name"] = "Celestial", ["text"] = "\"A powerful Celestial to go on missions for you, with a greatly increased chance of success.\"" }
entries[136985] = { ["name"] = "Can of Overheated Oil", ["text"] = "Quest Item\n\"The oil is so dark, it's like looking into a liquid void.\"" }
entries[136986] = { ["name"] = "Stag Blood Sample", ["text"] = "Quest Item\n\"Warm to the touch.\"" }
entries[136987] = { ["name"] = "Aged Snowplum Brandy", ["text"] = "Quest Item\n\"Aged for four years, an excellent vintage.\"" }
entries[137008] = { ["name"] = "Stormfury Diamond", ["text"] = "Binds when picked up\nStorm Artifact Relic\n+\nSell Price:" }
entries[137010] = { ["name"] = "Half-Full Bottle of Arcwine", ["text"] = "Binds when picked up\nUse: Gain 50 Ancient Mana.\n\"Thalyssra drank the other half.\"" }
entries[137011] = { ["name"] = "Corked Bottle", ["text"] = "Quest Item\n\"A gift from Ly'leth to Thalyssra.\"" }
entries[137014] = { ["name"] = "Achor, the Eternal Hunger", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Leather\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 4 Critical Strike\n+ 6 Haste\n+ 3 Mastery\nDurability 200 / 200\nClasses: Demon Hunter\nEquip: Vengeful Retreat heals you for 25% of your maximum health and grants you 20% Leech for 8 sec.\n\"Demon hunters possess a thirst for battle as endless as the legions of their most hated enemy.\"\nSell Price:" }
entries[137015] = { ["name"] = "Ekowraith, Creator of Worlds", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Leather\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 4 Critical Strike\n+ 3 Haste\n+ 6 Mastery\nDurability 200 / 200\nClasses: Druid\nEquip: Increase the effects of Thick Hide, Astral Influence, Feline Swiftness, and Ysera's Gift by 75%.\n\"We could not only evoke, but conjure a place of our own. And that everywhere... that has ever existed... it was all in service of our dream. Now please... Hear what I hear.\"\nSell Price:" }
entries[137016] = { ["name"] = "Sal'salabim's Lost Tunic", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Leather\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 6 Haste\n+ 4 Mastery\nDurability 200 / 200\nClasses: Monk\nEquip: When you use Keg Smash, the remaining cooldown on Breath of Fire is reset.\n\"Sal'salabim might have lost this when he blacked out for 6 hours...\"\nSell Price:" }
entries[137017] = { ["name"] = "Breastplate of the Golden Val'kyr", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Plate\n18 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 6 Haste\n+ 4 Versatility\nDurability 200 / 200\nClasses: Paladin\nEquip: Each enemy hit by Avenger's Shield reduces the remaining cooldown on Guardian of Ancient Kings by 3 sec.\n\"The remnant of a great commander who descended upon her enemies from the heavens, shining with the radiance of the sun.\"\nSell Price:" }
entries[137018] = { ["name"] = "Destiny Driver", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Plate\n18 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 6 Haste\n+ 4 Mastery\nDurability 200 / 200\nClasses: Warrior\nEquip: Intercepted attacks grant you and your Intercept target an absorb shield equal to 50% of the damage done by the attack for 10 sec.\n\"Bend time itself to protect the world from devastation.\"\nSell Price:" }
entries[137019] = { ["name"] = "Cenedril, Reflector of Hatred", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 4 Haste\n+ 2 Mastery\nClasses: Monk\nEquip: Touch of Karma deals 150% increased damage.\n\"If you know the enemy and know yourself, you need not fear the result of a hundred battles.\"\nSell Price:" }
entries[137020] = { ["name"] = "Whisper of the Nathrezim", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 [Strength or Intellect]\n+4 Stamina\n+ 4 Critical Strike\n+ 2 Haste\nClasses: Paladin\nEquip: Templar's Verdict and Divine Storm increase the damage of your next Templar's Verdict or Divine Storm within 4 sec by 15%.\n\"Pitiful... Is that the best you can do?\"\nSell Price:" }
entries[137021] = { ["name"] = "The Dreadlord's Deceit", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 Agility\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Mastery\nClasses: Rogue\nEquip: Subtlety\nEvery 2 sec, gain 25% increased damage for your next Shuriken Storm, stacking up to 30 times.\n\nAssassination, Outlaw\nEvery 2 sec, gain 35% increased damage for your next Fan of Knives, stacking up to 30 times.\n\"I've been preparing for you, young prince. I am Mal'Ganis. As you can see, your people are now mine...\"\nSell Price:" }
entries[137022] = { ["name"] = "Loramus Thalipedes' Sacrifice", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 3 Critical Strike\n+ 5 Haste\nDurability 95 / 95\nClasses: Demon Hunter\nEquip: Fel Rush deals 10% increased damage for each target hit.\n\"These boots are the only thing that remained after the Stone Knife of Sealing trapped Rakh'likh within Loramus the Defiled's body.\"\nSell Price:" }
entries[137023] = { ["name"] = "Promise of Elune, the Moon Goddess", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Haste\n+ 3 Mastery\nDurability 95 / 95\nClasses: Druid\nEquip: Lunar Strike and Solar Wrath deal 8% increased damage and grant Power of Elune, increasing the healing of your next Regrowth by 30% and reducing its cast time by 5%, stacking up to 20 times.\n\"When others receive life and energy from you, you too shall receive life and energy from me.\"\nSell Price:" }
entries[137024] = { ["name"] = "Ailuro Pouncers", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 5 Critical Strike\n+ 3 Haste\nDurability 95 / 95\nClasses: Druid\nEquip: Gain 1 stack of Predatory Swiftness every 15 sec. Additionally, Predatory Swiftness now stacks up to 3 times.\n\"The madness within Marl Wormthorn is said to have empowered these boots.\"\nSell Price:" }
entries[137025] = { ["name"] = "Skysec's Hold", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 3 Versatility\n+ 5 Mastery\nDurability 95 / 95\nClasses: Druid\nEquip: Frenzied Regeneration heals you for an additional 12% of your maximum health over 3 sec.\n\"During the Battle for Mount Hyjal, Skysec, guardian of Nordrassil, endured endless waves of scourge and legion. In the end, he proudly gave his life in defense of the ancient world tree.\"\nSell Price:" }
entries[137026] = { ["name"] = "Essence of Infusion", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 5 Haste\n+ 3 Mastery\nDurability 95 / 95\nClasses: Druid\nEquip: Tranquility heals targets below 60% health for 60% more.\n\"Feel nature flowing through your veins.\"\nSell Price:" }
entries[137027] = { ["name"] = "Firestone Walkers", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 5 Critical Strike\n+ 3 Haste\nDurability 95 / 95\nClasses: Monk\nEquip: Each enemy you hit with Breath of Fire reduces the cooldown of Fortifying Brew by 2 sec., up to a maximum of 6 sec.\n\"'Brother Adam and Brother David were brilliant mathematicians and monks, always blabbing about abacuses and parabolas.' -Brynild the Brewmaster\"\nSell Price:" }
entries[137028] = { ["name"] = "Ei'thas, Lunar Glides of Eramas", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Mastery\nDurability 95 / 95\nClasses: Monk\nEquip: Increases healing done by Vivify by 10%.\nEquip: Uplifting Trance increases your Vivify healing by an additional 10% and causes it to heal 1 additional target.\n\"Eramas Brightblaze always remarked how comfortable these were.\"\nSell Price:" }
entries[137029] = { ["name"] = "Katsuo's Eclipse", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Haste\n+ 3 Mastery\nDurability 95 / 95\nClasses: Monk\nEquip: Reduce the cost of Fists of Fury by 1 Chi.\n\"Said Kaulder to his brother Katsuo: 'With training, your reactions can become faster and your fists can become more furious than any foe can handle.'\"\nSell Price:" }
entries[137030] = { ["name"] = "Duskwalker's Footpads", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Haste\n+ 3 Mastery\nDurability 95 / 95\nClasses: Rogue\nEquip: The remaining cooldown on Vendetta is reduced by 1 sec for every 65 Energy you expend.\n\"If an SI:7 agent like Caelvana has you in her sights, you'd better run. You better run far, and you better do it quickly.\"\nSell Price:" }
entries[137031] = { ["name"] = "Thraxi's Tricksy Treads", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 5 Critical Strike\n+ 3 Mastery\nDurability 95 / 95\nClasses: Rogue\nEquip: Dispatch deals increased damage equal to 20% of your increased movement speed.\n\"Thraxi often disguised herself as a brewmaster monk to deceive her enemies.\"\nSell Price:" }
entries[137032] = { ["name"] = "Shadow Satyr's Walk", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 5 Haste\n+ 3 Mastery\nDurability 95 / 95\nClasses: Rogue\nEquip: Shadowstrike restores 3 Energy plus an additional 1 Energy for every 3 yds between you and your target.\n\"While the exact origins of the Shadow satyr are unidentified, they are known to be incorporeal creatures that not only exist inside the Emerald Nightmare but in places on Azeroth as well.\"\nSell Price:" }
entries[137033] = { ["name"] = "Ullr's Feather Snowshoes", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Mail\n7 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Mastery\nDurability 95 / 95\nClasses: Hunter\nEquip: The remaining cooldown on Trueshot is reduced by 0.8 sec each time you cast a damaging Shot.\n\"They provided the huntress with a feeling of weightlessness- a calm and serenity amid the storm.\"\nSell Price:" }
entries[137034] = { ["name"] = "Nesingwary's Trapping Treads", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Mail\n7 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 3 Haste\n+ 5 Mastery\nDurability 95 / 95\nClasses: Hunter\nEquip: Gain 25 Focus when one of your traps is triggered.\n\"Something with very large teeth tried taking a bite out of these boots.\"\nSell Price:" }
entries[137035] = { ["name"] = "The Deceiver's Blood Pact", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Mail\n7 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 5 Critical Strike\n+ 3 Haste\nDurability 95 / 95\nClasses: Shaman\nEquip: Earth Shock has a 20% chance to refund all of the Maelstrom spent. (Proc chance: 20%)\n\"Ner'zhul, Elder Shaman of the Shadowmoon Clan, wanted to save his people and finally obtain the power and respect he so dearly desired. But he was deceived...\"\nSell Price:" }
entries[137036] = { ["name"] = "Elemental Rebalancers", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Mail\n7 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 3 Haste\n+ 5 Mastery\nDurability 95 / 95\nClasses: Shaman\nEquip: Allies within your Healing Rain receive 10% increased healing from your other healing spells.\n\"Originally used by a powerful doomguard to rain down fiery death, these were repurposed for a more benevolent cause in order to balance out the destruction they had previously caused.\"\nSell Price:" }
entries[137037] = { ["name"] = "Uvanimor, the Unbeautiful", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 8 Haste\n+ 6 Mastery\n\nPrismatic Socket\n\nClasses: Death Knight\nEquip: Your [ Sludge Belcher : abomination's / ghoul's] melee attacks have a 10% chance to activate 1 of your runes.\n\"The corrupting power of the Nightwell flows through this ring, allowing the wielder to siphon power from those under their command.\"\nSell Price:" }
entries[137038] = { ["name"] = "Anger of the Half-Giants", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 9 Critical Strike\n+ 5 Haste\n\nPrismatic Socket\n\nClasses: Demon Hunter\nEquip: [ Demon Blades / Demon's Bite] generates an additional 1 to 14 Fury.\n\"Those oversized Vrykul are not the first thing you want to run into in Northrend. Try the undead of Borean Tundra instead.\"\nSell Price:" }
entries[137039] = { ["name"] = "Impeccable Fel Essence", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 9 Haste\n+ 5 Mastery\n\nPrismatic Socket\n\nClasses: Druid\nEquip: The remaining cooldown on [ Incarnation: Chosen of Elune / Celestial Alignment] is reduced by 1 sec for every 12 Astral Power you expend.\n\"The druids of the Emerald Circle manipulated the fel energy within this stone to enhance their attunement with the wild.\"\nSell Price:" }
entries[137040] = { ["name"] = "Chatoyant Signet", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 8 Critical Strike\n+ 6 Haste\n\nPrismatic Socket\n\nClasses: Druid\nEquip: Increases your Energy regeneration by 5% and maximum Energy by 100 while in Cat Form.\n\"The fire within Leyara enchants this signet. You can feel that she has finally found peace.\"\nSell Price:" }
entries[137041] = { ["name"] = "Dual Determination", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 9 Critical Strike\n+ 5 Mastery\n\nPrismatic Socket\n\nClasses: Druid\nEquip: Survival Instincts gains 1 additional charge and recharges 15% faster.\n\"Druids of the Claw have the ability to transform, becoming either faster or tougher. They typically choose the latter.\"\nSell Price:" }
entries[137042] = { ["name"] = "Tearstone of Elune", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 9 Haste\n+ 5 Mastery\n\nPrismatic Socket\n\nClasses: Druid\nEquip: Allies healed by your Wild Growth have a 15% chance to also gain Rejuvenation. (Proc chance: 15%)\n\"The myth surrounding Elune, one of the few true deities of Azeroth, suggest her true identity might not yet have been fully understood.\"\nSell Price:" }
entries[137043] = { ["name"] = "Frizzo's Fingertrap", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 9 Haste\n+ 5 Mastery\n\nPrismatic Socket\n\nClasses: Hunter\nEquip: Increases damage done by [ Butchery / Carve] by 10%.\nEquip: When you Carve an enemy affected by Lacerate, Lacerate spreads to 1 other target hit by Carve .\n\"Apply a little butter and it comes right off!\"\nSell Price:" }
entries[137044] = { ["name"] = "Jewel of the Lost Abbey", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 8 Critical Strike\n+ 6 Mastery\n\nPrismatic Socket\n\nClasses: Monk\nEquip: Increases the duration of Stagger by 3.0 sec.\n\"Originally a gift from the mage, Veri'thas, this trinket was allegedly stolen from the Lost Abbey after a conflict between the monks and the elves.\"\nSell Price:" }
entries[137045] = { ["name"] = "Eye of Collidus the Warp-Watcher", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 8 Haste\n+ 6 Mastery\n\nPrismatic Socket\n\nClasses: Monk\nEquip: Each time Soothing Mist heals, the absorb amount of your next Life Cocoon is increased by 3%, stacking up to 50 times.\n\"Well... one of his eyes.\"\nSell Price:" }
entries[137046] = { ["name"] = "Ilterendi, Crown Jewel of Silvermoon", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 8 Critical Strike\n+ 6 Mastery\n\nPrismatic Socket\n\nClasses: Paladin\nEquip: Judgment increases all healing you do by 15% for 5 sec.\n\"Silvermoon was constructed out of radiant white stone and adorned in crimson tapestry. However, the city's renown was not merely for its beauty. Silvermoon is a seat of magical learning and home to master manipulators of mana.\"\nSell Price:" }
entries[137047] = { ["name"] = "Heathcliff's Immortality", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 8 Haste\n+ 6 Mastery\n\nPrismatic Socket\n\nClasses: Paladin\nEquip: You take 4% less damage while standing in your Consecration.\n\"Heathcliff, known as the Immortal Object, was said to be immune to any grave injury. Some questioned whether the Blood Knight's fortitude transcended the natural laws of the world.\"\nSell Price:" }
entries[137048] = { ["name"] = "Liadrin's Fury Unleashed", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 8 Critical Strike\n+ 6 Haste\n\nPrismatic Socket\n\nClasses: Paladin\nEquip: While Avenging Wrath is active, you gain 1 Holy Power every 6 sec.\n\"We were betrayed by the man we called our prince. I pledge the blades of my Blood Knights to the defeat of Kil'jaeden and the restoration of Silvermoon. We will fight beside you, A'dal.\"\nSell Price:" }
entries[137049] = { ["name"] = "Insignia of Ravenholdt", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 9 Critical Strike\n+ 5 Haste\n\nPrismatic Socket\n\nClasses: Rogue\nEquip: Your single-target combo-point generating attacks deal 15% additional damage as Shadow to all targets within 15 yards in front of you.\n\"An insignia only given to those who have demonstrated mastery of the shadows, and killed in service to Ravenholdt.\"\nSell Price:" }
entries[137050] = { ["name"] = "Eye of the Twisting Nether", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 9 Haste\n+ 5 Mastery\n\nPrismatic Socket\n\nClasses: Shaman\nEquip: Damaging enemies with your Fire, Frost, or Nature abilities increases all damage you deal by 1.5% for 8 sec. Each element adds a separate application.\n\"In the nether, though the elements of the world are twisted and barely recognizable, their power is without equal.\"\nSell Price:" }
entries[137051] = { ["name"] = "Focuser of Jonat, the Elder", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 9 Critical Strike\n+ 5 Haste\n\nPrismatic Socket\n\nClasses: Shaman\nEquip: Healing Wave and Healing Surge increase the healing of your next Chain Heal by 10%, stacking up to 5 times.\n\"Under the training of Jonat Han, new shamans of the Dragonflayer clan mastered the ways of the waters - healing the one and the many.\"\nSell Price:" }
entries[137052] = { ["name"] = "Ayala's Stone Heart", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 8 Critical Strike\n+ 6 Mastery\n\nPrismatic Socket\n\nClasses: Warrior\nEquip: Your attacks have a chance to make your next Execute cost no Rage and be usable on any target, regardless of health level.\n\"In the pits of Valhalas, Ayala the Relentless cut down foe after foe on his way to legend. Becoming more lethal as his opponents weakened, he was truly terrifying to spectate.\"\nSell Price:" }
entries[137053] = { ["name"] = "Kazzalax, Fujieda's Fury", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 Strength\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Mastery\nClasses: Warrior\nEquip: Bloodthirst increases all damage you deal and all healing you take by 1% for 10 sec, stacking up to 4 times.\n\"Jinyu whisper tales of the great warrior, Fujieda, who slew a mighty fel demon after lying in wait in a shallow pool for hours.\"\nSell Price:" }
entries[137054] = { ["name"] = "The Walls Fell", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 8 Critical Strike\n+ 6 Haste\n\nPrismatic Socket\n\nClasses: Warrior\nEquip: Shield Slam generates an additional 2 Rage and reduces the remaining cooldown of Shield Wall by 4 sec.\n\"Midst the third war, when the walls of Kalimdor defenders fell, Shaka, the Ancient of War, refused.\"\nSell Price:" }
entries[137055] = { ["name"] = "Zevrim's Hunger", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 9 Critical Strike\n+ 5 Mastery\n\nPrismatic Socket\n\nClasses: Hunter\nEquip: Increases all damage done by 3%.\nEquip: Marked Shot has a 15% chance to not remove Hunter's Mark.\n\"Its power was extracted from hunters who were sacrificed in Dire Maul.\"\nSell Price:" }
entries[137056] = { ["name"] = "Luffa Wrappings", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Leather\n4 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 2 Critical Strike\n+ 3 Haste\nDurability 70 / 70\nClasses: Druid\nEquip: Increases the damage and radius of Thrash by 25%.\n\"Nothing works quite like a good luffa.\"\nSell Price:" }
entries[137057] = { ["name"] = "Hidden Master's Forbidden Touch", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHands Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 3 Haste\n+ 4 Mastery\nDurability 70 / 70\nClasses: Monk\nEquip: Touch of Death deals 40% increased damage and can be used a second time within 5 sec before its cooldown is triggered.\n\"For thousands of years, ancient understandings of lifeflow manipulation have been passed in secret from one master to another.\"\nSell Price:" }
entries[137058] = { ["name"] = "Praetorian's Tidecallers", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHands Mail\n7 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Haste\n+ 3 Mastery\nDurability 70 / 70\nClasses: Shaman\nEquip: Increases the duration of Healing Stream Totem, Healing Tide Totem, and Spirit Link Totem by 20%.\n\"Working together to defeat Azeroth's greatest enemies, the best minds congregated in a forum dedicated to intellectual discussion and war strategy while their champions battled on the frontlines.\"\nSell Price:" }
entries[137059] = { ["name"] = "Tyr's Hand of Faith", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHands Plate\n10 Armor\n+4 [Strength or Intellect]\n+6 Stamina\n+ 5 Critical Strike\n+ 3 Haste\nDurability 70 / 70\nClasses: Paladin\nEquip: Reduces the cooldown of Lay on Hands by 70%.\n\"After losing his hand to the massive proto-dragon Galakrond, Jotun forged Tyr a new one.\"\nSell Price:" }
entries[137060] = { ["name"] = "Archavon's Heavy Hand", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHands Plate\n10 Armor\n+4 [Strength or Intellect]\n+6 Stamina\n+ 3 Critical Strike\n+ 4 Haste\nDurability 70 / 70\nClasses: Warrior\nEquip: Mortal Strike costs 8 less Rage.\n\"Deep within the vault protected by Wintergrasp, Archavon the Stone Watcher was hateful of all trespassers.\"\nSell Price:" }
entries[137061] = { ["name"] = "Raddon's Cascading Eyes", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Leather\n6 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 6 Critical Strike\n+ 4 Haste\nDurability 120 / 120\nClasses: Demon Hunter\nEquip: The remaining cooldown on Eye Beam is reduced by 0.3 sec each time it hits an enemy, up to a maximum of 20 sec.\n\"As the world... goes by... we'll go on forever.\"\nSell Price:" }
entries[137062] = { ["name"] = "The Emerald Dreamcatcher", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Leather\n6 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 4 Critical Strike\n+ 6 Mastery\nDurability 120 / 120\nClasses: Druid\nEquip: Starsurge reduces the Astral Power cost of your Starsurges by 5 for 5 sec. Stacks up to 2 times.\n\"Ysera dreams and the world trembles.\"\nSell Price:" }
entries[137063] = { ["name"] = "Fundamental Observation", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Leather\n6 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 4 Critical Strike\n+ 6 Mastery\nDurability 120 / 120\nClasses: Monk\nEquip: Zen Meditation has 50% reduced cooldown and is no longer cancelled when you move or when you are hit by melee attacks.\n\"Sit back, relax, and observe the world around you.\"\nSell Price:" }
entries[137064] = { ["name"] = "The Shadow Hunter's Voodoo Mask", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Mail\n9 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 3 Critical Strike\n+ 4 Haste\n+ 6 Mastery\nDurability 120 / 120\nClasses: Hunter\nEquip: Heal for 20% of your maximum health when you activate Feign Death then heal for an additional 5% of your maximum health every sec afterwards for 10 sec while still Feigning Death.\n\"'If dey want to kill me, dey betta' kill me da first time. Dey betta' kill me dead. Dey betta' kill me when I'm in my sleep.' -Vol'jin, after surviving Garrosh's assassination attempt.\"\nSell Price:" }
entries[137065] = { ["name"] = "Justice Gaze", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Plate\n13 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 6 Haste\n+ 4 Mastery\nDurability 120 / 120\nClasses: Paladin\nEquip: Hammer of Justice deals 204% Holy damage, generates 1 Holy Power, and has 75% reduced cooldown when used against an enemy above 75% health.\n\"This helm was once worn by Highlord Alexandros Mograine, and had things gone differently, would have been passed on to his sons, Renault and Darion Mograine.\"\nSell Price:" }
entries[137066] = { ["name"] = "Cloak of Fel Flames", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 Agility\n+4 Stamina\n+ 3 Haste\n+ 2 Versatility\nClasses: Demon Hunter\nEquip: You take 15% reduced magic damage while Immolation Aura is active.\n\"Appearing like any other found in the molten depths, this one appears to burn with a greater purpose.\"\nSell Price:" }
entries[137067] = { ["name"] = "Elize's Everlasting Encasement", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nLegs Leather\n7 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 6 Critical Strike\n+ 4 Mastery\nDurability 145 / 145\nClasses: Druid\nEquip: Thrash can stack up to 2 more times.\n\"'100% all natural fury' was an apt description of its owner during the Sundering.\"\nSell Price:" }
entries[137068] = { ["name"] = "Leggings of The Black Flame", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nLegs Leather\n7 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 6 Critical Strike\n+ 4 Haste\nDurability 145 / 145\nClasses: Monk\nEquip: Thunder Focus Tea also grants Effuse, Enveloping Mist, Essence Font, Renewing Mist, and Vivify 1 extra charge at random.\n\"The Black Flame specializes in providing the finest services and entertainment money can buy, whether they happen to be hard to find items, gladiatorial combat, or lucrative games of chance.\"\nSell Price:" }
entries[137069] = { ["name"] = "Will of Valeera", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nLegs Leather\n7 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 6 Critical Strike\n+ 4 Haste\n+ 3 Mastery\nDurability 145 / 145\nClasses: Rogue\nEquip: Feint heals you for 20% of your maximum health over 5 sec.\n\"At a young age, Valeera survived the death of her parents, imprisonment, and slavery. Her enemies have always underestimated her will to survive.\"\nSell Price:" }
entries[137070] = { ["name"] = "Tyelca, Ferren Marcus's Stature", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nLegs Plate\n16 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 4 Critical Strike\n+ 6 Mastery\nDurability 145 / 145\nClasses: Paladin\nEquip: Avenger's Shield deals 20% increased damage and jumps to 2 additional targets.\n\"Power comes from strength, and true strength comes from strong legs bolting you to the ground.\"\nSell Price:" }
entries[137071] = { ["name"] = "Runemaster's Pauldrons", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Leather\n6 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 5 Critical Strike\n+ 3 Haste\nDurability 120 / 120\nClasses: Demon Hunter\nEquip: Metamorphosis resets the remaining cooldown on all your Sigils and grants you 1 charge of Demon Spikes.\n\"Molgeim of the Assembly of Iron mastered the use of runes for a myriad of devastating effects.\"\nSell Price:" }
entries[137072] = { ["name"] = "Aman'Thul's Wisdom", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Leather\n6 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 3 Critical Strike\n+ 4 Mastery\nDurability 120 / 120\nClasses: Druid\nEquip: When your Rejuvenation heals a full health target, its duration is increased by 3 sec, up to a maximum total increase of 9 sec per cast.\n\"Unto you is charged the great task of keeping the purity of time. Know that there is only one true timeline, though there are those who would have it otherwise. You must protect it.\"\nSell Price:" }
entries[137073] = { ["name"] = "Unison Spaulders", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Leather\n6 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 5 Haste\n+ 3 Mastery\nDurability 120 / 120\nClasses: Monk\nEquip: Soothing Mist heals a second injured ally within 15 yds for 50% of the amount healed.\n\"Every place you've ever imagined- it is real. It is a fictional city in your mind and you know every corner of it. Your mind is a world. Each of us is a place.\"\nSell Price:" }
entries[137074] = { ["name"] = "Echoes of the Great Sundering", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Mail\n8 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 3 Haste\n+ 4 Mastery\nDurability 120 / 120\nClasses: Shaman\nEquip: Earth Shock has up to a 50% chance, based on Maelstrom spent, to cause your next Earthquake to be free and deal 100% increased damage.\n\"10,000 years ago, the Well of Eternity imploded. The effects are still felt today.\"\nSell Price:" }
entries[137075] = { ["name"] = "Tak'theritrix's Shoulderpads", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Plate\n12 Armor\n+4 [Strength or Intellect]\n+6 Stamina\n+ 3 Haste\n+ 4 Mastery\nDurability 120 / 120\nClasses: Death Knight\nEquip: Dark Transformation also empowers your [ Dark Arbiter / Gargoyle] and Army of the Dead for 30 sec, increasing their damage by 40%.\n\"During the first invasion of Azeroth, legion commander Tak'theritrix was key in peeling apart the initial night elf defense.\"\nSell Price:" }
entries[137076] = { ["name"] = "Obsidian Stone Spaulders", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Plate\n12 Armor\n+4 [Strength or Intellect]\n+6 Stamina\n+ 5 Critical Strike\n+ 3 Haste\nDurability 120 / 120\nClasses: Paladin\nEquip: 30% of any healing done to you heals all allies affected by your Beacons, divided evenly.\n\"These appear to emanate the same power as the dark portal.\"\nSell Price:" }
entries[137077] = { ["name"] = "Weight of the Earth", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nLegs Plate\n16 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 6 Critical Strike\n+ 4 Mastery\nDurability 145 / 145\nClasses: Warrior\nEquip: Heroic Leap's radius is increased by 100% and all enemies damaged by your Heroic Leap are also affected by Colossus Smash.\n\"All living creatures trust in the stillness of the earth. They know nothing of the currents that flow beneath its surface. They do not comprehend its weight. They cannot understand its power.\"\nSell Price:" }
entries[137078] = { ["name"] = "The Dark Titan's Advice", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Haste\nDurability 70 / 70\nClasses: Druid\nEquip: Lifebloom's final healing is increased by 200% and Lifebloom's periodic healing has a 5% chance heal for its final healing amount.\n\"Patience, young one, and you someday will have it all.\"\nSell Price:" }
entries[137079] = { ["name"] = "Gai Plin's Soothing Sash", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 3 Versatility\n+ 5 Mastery\nDurability 70 / 70\nClasses: Monk\nEquip: Purifying Brew instantly heals you for 25% of the purified Stagger damage.\n\"Gai Plin extracted the healing powers of the Ru'shan River to infuse this belt with its soothing sensations.\"\nSell Price:" }
entries[137080] = { ["name"] = "Roar of the Seven Lions", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Mail\n7 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Haste\n+ 3 Mastery\nDurability 70 / 70\nClasses: Hunter\nEquip: Bestial Wrath reduces the Focus cost of all your abilities by 15%.\n\"Woven from the manes of the fabled Seven Lions, this belt was crafted by the night elf sentinel Tyven.\"\nSell Price:" }
entries[137081] = { ["name"] = "War Belt of the Sentinel Army", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Mail\n7 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Haste\n+ 3 Mastery\nDurability 70 / 70\nClasses: Hunter\nEquip: Each enemy you hit with Multi-Shot increases the damage of your next Aimed Shot by 10%, stacking up to 20 times.\n\"Sentinels are the expert marksmen and elite fighters among the night elves. Few warriors can match the proud archers' speed and cunning.\"\nSell Price:" }
entries[137082] = { ["name"] = "Helbrine, Rope of the Mist Marauder", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Mail\n7 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Haste\nDurability 70 / 70\nClasses: Hunter\nEquip: The first time Harpoon hits a target, your damage done to the target is increased by up to 30% for 10 sec based on distance to the target.\n\"Ghostly howls hang in the fog long after Helheim has taken another.\"\nSell Price:" }
entries[137083] = { ["name"] = "Pristine Proto-Scale Girdle", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Mail\n7 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Mastery\nDurability 70 / 70\nClasses: Shaman\nEquip: Lava Burst deals an additional (13.5% of Spell Power) damage over 6 sec. Stacks up to 5 times.\n\"Crafted from a massive proto-dragon scale that appears ancient, yet feels still hot.\"\nSell Price:" }
entries[137084] = { ["name"] = "Akainu's Absolute Justice", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Mail\n6 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 4 Critical Strike\n+ 2 Mastery\nDurability 70 / 70\nClasses: Shaman\nEquip: Lava Lash deals 50% increased damage while your weapons are enhanced by both Flametongue and Frostbrand.\n\"His molten powers could shape an entire landscape.\"\nSell Price:" }
entries[137085] = { ["name"] = "Intact Nazjatar Molting", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Mail\n7 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 5 Critical Strike\n+ 3 Haste\nDurability 70 / 70\nClasses: Shaman\nEquip: Casting Riptide on a target below 40% health resets the remaining cooldown on Riptide.\n\"The naga of Nazjatar are masters of sorcery and natural dwellers of the ocean deeps. It makes sense that wearing their discarded skin would grant you a greater control over the tides.\"\nSell Price:" }
entries[137086] = { ["name"] = "Chain of Thrayn", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Plate\n10 Armor\n+4 [Strength or Intellect]\n+6 Stamina\n+ 3 Critical Strike\n+ 5 Haste\nDurability 70 / 70\nClasses: Paladin\nEquip: Retribution\nAvenging Wrath increases healing done by an additional 50% and increases damage done by an additional 10%.\n\nHoly\nAvenging Wrath increases healing done by an additional 25% and increases damage done by an additional 10%.\n\nProtection\nAvenging Wrath increases healing done by an additional 50% and increases damage done by an additional 10%.\n\"The prayer of an ancient Valhalas champion resonates through the links: 'If you stand in the light, you will never stand alone.'\"\nSell Price:" }
entries[137087] = { ["name"] = "Naj'entus's Vertebrae", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Plate\n10 Armor\n+4 [Strength or Intellect]\n+6 Stamina\n+ 3 Critical Strike\n+ 5 Mastery\nDurability 70 / 70\nClasses: Warrior\nEquip: If Whirlwind hits 3 or more enemies, it hits them 1 additional time.\n\"Few naga matched the strength of Naj'entus, champion of Lady Vashj and servant to Illidan Stormrage.\"\nSell Price:" }
entries[137088] = { ["name"] = "Ceann-Ar Charger", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Plate\n13 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 6 Haste\n+ 4 Mastery\nDurability 120 / 120\nClasses: Warrior\nEquip: Gain 8 Rage whenever you Enrage.\n\"Legendary fighters always take their opponents head-on.\"\nSell Price:" }
entries[137089] = { ["name"] = "Thundergod's Vigor", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Plate\n10 Armor\n+4 [Strength or Intellect]\n+6 Stamina\n+ 5 Haste\n+ 3 Versatility\nDurability 70 / 70\nClasses: Warrior\nEquip: Each enemy you hit with Thunder Clap reduces the remaining cooldown on Demoralizing Shout by 3 sec.\n\"And the god of thunder struck down transgressors with great fury and vengeance...\"\nSell Price:" }
entries[137090] = { ["name"] = "Mo'arg Bionic Stabilizers", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Leather\n4 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 4 Critical Strike\n+ 2 Mastery\nDurability 70 / 70\nClasses: Demon Hunter\nEquip: Throw Glaive deals 25% increased damage for each enemy hit.\n\"If you can stabilize a saw you can stabilize a glaive.\"\nSell Price:" }
entries[137091] = { ["name"] = "The Defiler's Lost Vambraces", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Leather\n4 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 2 Haste\n+ 3 Mastery\n+ 3 Avoidance\nDurability 70 / 70\nClasses: Demon Hunter\nEquip: Soul Cleave reduces the remaining cooldown on a random Sigil by 8 sec. (500ms cooldown)\n\"While in battle with Loramus Thalipedes atop the Rise of the Defiler, these vambraces flew off the wrists of Razelikh toward the Dark Portal.\"\nSell Price:" }
entries[137092] = { ["name"] = "Oneth's Intuition", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Leather\n4 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Haste\nDurability 70 / 70\nClasses: Druid\nEquip: Starsurge and Starfall each have a 20% chance to make the other free. (Proc chance: 20%)\n\"Aglaya would have called it Oneth's Overconfidence.\"\nSell Price:" }
entries[137094] = { ["name"] = "The Wildshaper's Clutch", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHands Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Haste\nDurability 70 / 70\nClasses: Druid\nEquip: Critical damage from your Bleeds have a 30% chance to trigger Primal Fury. (Proc chance: 30%)\n\"Twisted druids of the Wildspawn hoped to one day wield the power that Alzzin bestowed upon these.\"\nSell Price:" }
entries[137095] = { ["name"] = "Edraith, Bonds of Aglaya", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Leather\n4 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Haste\nDurability 70 / 70\nClasses: Druid\nEquip: Swiftmend extends the duration of your heal over time effects on the target by 10 sec.\n\"Crafted from the hide of an ancient bull that had been graced with a disposition of eternal happiness.\"\nSell Price:" }
entries[137096] = { ["name"] = "Petrichor Lagniappe", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Leather\n4 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 4 Haste\n+ 2 Mastery\nDurability 70 / 70\nClasses: Monk\nEquip: The remaining cooldown on Revival is reduced by 2.0 sec each time you cast Renewing Mist.\n\"Ah... It smells like rain today.\"\nSell Price:" }
entries[137097] = { ["name"] = "Drinking Horn Cover", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Leather\n4 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 2 Critical Strike\n+ 4 Haste\nDurability 70 / 70\nClasses: Monk\nEquip: The duration of Storm, Earth, and Fire is extended by 0.4 sec for every Chi you spend. (100ms cooldown)\n\"The hearty vrykul of Northrend were able to weather all elements if they had enough drink.\"\nSell Price:" }
entries[137098] = { ["name"] = "Zoldyck Family Training Shackles", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Leather\n4 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 2 Haste\n+ 4 Mastery\nDurability 70 / 70\nClasses: Rogue\nEquip: Your Poisons and Bleeds deal 30% increased damage to targets below 30% health.\n\"The Zoldyck family are trained from birth in the art of assassination. In the lower levels of their estate, members learn to resist the effects of and master the use of deadly poisons.\"\nSell Price:" }
entries[137099] = { ["name"] = "Greenskin's Waterlogged Wristcuffs", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Leather\n4 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Haste\nDurability 70 / 70\nClasses: Rogue\nEquip: Between the Eyes has a 20% chance per Combo Point to increase the damage of your next Pistol Shot by 200%.\n\"In the lawless world of tavern brawls and spontaneous duels, accuracy is of critical importance.\"\nSell Price:" }
entries[137100] = { ["name"] = "Denial of the Half-Giants", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Leather\n4 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 2 Critical Strike\n+ 4 Mastery\nDurability 70 / 70\nClasses: Rogue\nEquip: Your finishing moves extend the duration of Shadow Blades by 0.2 sec for each combo point spent.\n\"If you think a Tauren trying to hide in the shadows is laughable, you should see one of those Vrykul half-giants try to be sneaky in broad daylight!\"\nSell Price:" }
entries[137101] = { ["name"] = "Call of the Wild", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Mail\n6 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Haste\nDurability 70 / 70\nClasses: Hunter\nEquip: Reduces the cooldown of all Aspects by 35%.\n\"Hunters have a powerful connection to the wild - the ability to call upon the animal aspects to empower themselves and to befriend even the wildest of beasts.\"\nSell Price:" }
entries[137102] = { ["name"] = "Al'Akir's Acrimony", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Mail\n6 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 3 Haste\n+ 2 Mastery\nDurability 70 / 70\nClasses: Shaman\nEquip: Chain Lightning deals 5% increased damage to each subsequent target.\n\"Lightning still courses through these bindings. Your power feels infinite and ever increasing...\"\nSell Price:" }
entries[137103] = { ["name"] = "Storm Tempests", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Mail\n7 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Haste\nDurability 70 / 70\nClasses: Shaman\nEquip: Enemies hit by your Stormstrike become lightning charged for 15 sec, zapping a nearby enemy every 1 sec for 5% Nature damage.\n\"Crafted from the scales of an ancient storm dragon, these release uncontrollable magic at everything nearby.\"\nSell Price:" }
entries[137104] = { ["name"] = "Nobundo's Redemption", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Mail\n6 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Mastery\nDurability 70 / 70\nClasses: Shaman\nEquip: Chain Heal reduces the mana cost of your next Healing Surge by 50%.\n\"Farseer Nobundo left the city broken, but returned empowered by the elements.\"\nSell Price:" }
entries[137105] = { ["name"] = "Uther's Guard", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Plate\n9 Armor\n+3 [Strength or Intellect]\n+4 Stamina\n+ 3 Critical Strike\n+ 3 Haste\n+ 2 Mastery\nDurability 70 / 70\nClasses: Paladin\nEquip: Your Blessing of Freedom [ Blessing of Sacrifice : Blessing of Sacrifice ] and [ Blessing of Spellwarding / Blessing of Protection] have 50% increased duration and heal the target for 15% of their maximum health.\n\"Uther the Lightbringer, leader of the Silver Hand, commanded such presence on the battlefield that his knights at times seemed both invincible and unstoppable.\"\nSell Price:" }
entries[137107] = { ["name"] = "Mannoroth's Bloodletting Manacles", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Plate\n9 Armor\n+3 [Strength or Intellect]\n+4 Stamina\n+ 2 Haste\n+ 4 Versatility\n+ 3 Mastery\nDurability 70 / 70\nClasses: Warrior\nEquip: You heal 1% of maximum health for every 10 Rage you spend.\n\"Come, feast in my blood, and soon you shall feast in the blood of your enemies.\"\nSell Price:" }
entries[137108] = { ["name"] = "Kakushan's Stormscale Gauntlets", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHands Plate\n10 Armor\n+4 [Strength or Intellect]\n+6 Stamina\n+ 3 Versatility\n+ 4 Mastery\nDurability 70 / 70\nClasses: Warrior\nEquip: [ Devastator : Your auto attacks increase / Devastate increases] the damage done and Rage generated by your next Shield Slam or Thunder Clap by 20%.\n\"The great warrior Kakushan created these from skins of the Stormscale after he and Ivagont laid waste to their villages in Darkshore. While the naga fled in fear, the Vrykul drank the blood of their tribe members.\"\nSell Price:" }
entries[137109] = { ["name"] = "X'anshi, Shroud of Archbishop Benedictus", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 Intellect\n+4 Stamina\n+ 4 Critical Strike\n+ 2 Mastery\nClasses: Priest\nEquip: After Spirit of Redemption expires, you will revive at up to 100% health, based on your effectiveness during Spirit of Redemption. After reviving, you cannot benefit from Spirit of Redemption for 10 min.\n\"Is it possible to succeed without any act of betrayal?\"\nSell Price:" }
