entries[137220] = { ["name"] = "March of the Legion", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 8 Critical Strike\n+ 5 Haste\n+ 4 Mastery\n\nPrismatic Socket\n\nClasses: Monk\nEquip: Windwalking increases movement speed by an additional 15%.\n\"From his seat upon the Throne of Kil'jaeden, Doom Lord Kazzak raised his sword and called the demonic army into battle.\"\nSell Price:" }
