entries[137223] = { ["name"] = "Seal of Necrofantasia", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 9 Critical Strike\n+ 5 Mastery\n\nPrismatic Socket\n\nClasses: Death Knight\nEquip: [ Hungering Rune Weapon / Empower Rune Weapon] gains 1 additional charge and recharges 10% faster.\n\"Dark whispers from the Twisting Nether suggest that this seal was forged by the Nathrezim before the Third War, and given to one of the scourge's most powerful lieutenants.\"\nSell Price:" }
entries[137225] = { ["name"] = "Thunderfury, Blessed Blade of the Windseeker", ["text"] = "Binds when picked up\nUnique\nOne-Hand Sword\n3 - 7 Damage Speed 2.60\n(1.9 damage per second)\n+1 Agility\n+1 Stamina\n+1 Fire Resistance\n+1 Nature Resistance\nSell Price:" }
