entries[137537] = { ["name"] = "Tirathon's Betrayal", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 Agility\nUse: Empower yourself with dark energy, causing your attacks to have a chance to inflict 19 additional Shadow damage and grant you a shield for 21 .\n\nLasts 15 sec. (1 Min, 15 Sec Cooldown)\nSell Price:" }
entries[137538] = { ["name"] = "Orb of Torment", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Haste\nUse: Sap the soul of your target for 20 sec, causing you to be healed for 50% of the damage you deal to them, up to 3008 total healing. (2 Min Cooldown)\nSell Price:" }
entries[137539] = { ["name"] = "Faulty Countermeasure", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Critical Strike\nUse: Sheathe your weapons in ice for 30 sec, giving your melee attacks a chance to cause 45 additional Frost damage and slow the target's movement speed by 20% for 8 sec. (2 Min Cooldown)\nSell Price:" }
entries[137540] = { ["name"] = "Concave Reflecting Lens", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Critical Strike\nEquip: Your healing spells have a chance to launch a Pulse at your target, healing them for 52 and bouncing to up to 3 additional targets.\nSell Price:" }
entries[137541] = { ["name"] = "Moonlit Prism", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Haste\nUse: Increases your Agility or Intellect by 1 for 20 sec. Your ranged attacks and spells cause this effect to stack, up to 20 times. (400ms cooldown) (1 Min, 30 Sec Cooldown)\nSell Price:" }
