entries[137570] = { ["name"] = "Bloodfang Cocoon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a rideable Bloodfang Widow.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Its long, serrated limbs drip with the blood of its enemies and/or mate.\"\nVendor:\nThe Mad Merchant" }
entries[137571] = { ["name"] = "Archmage Vargoth's Journal", ["text"] = "Quest Item\nUnique\n\"A brand new journal titled, 'The Nightborne Soulstone.'\"" }
entries[137572] = { ["name"] = "Zoarg's Head", ["text"] = "Quest Item\n\"Otherwise indistinguishable from other felhounds, this particular demon has an extra set of razor-sharp teeth.\"" }
entries[137573] = { ["name"] = "Reins of the Llothien Prowler", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Llothien Prowler.\nSummons and dismisses your Llothien Prowler.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These sleek foxes can prowl amongst newly-fallen leaves without making a sound, even at this size.\"\nQuest:\nVolpin the Elusive\nZone:\nSuramar" }
entries[137574] = { ["name"] = "Living Infernal Core", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a rideable Felblaze Infernal.\nSummons and dismisses your Felblaze Infernal .\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"The Illidari were able to break one of these fiery beasts for use as an unstoppable, fearless mount against the Legion.\"\nDrop:\nGul'dan\nZone:\nThe Nighthold" }
entries[137575] = { ["name"] = "Fiendish Hellfire Core", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a rideable Hellfire Infernal.\nSummons and dismisses your Hellfire Infernal.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"From the bowels of the nether is summoned a creature of pure hatred, bent on burning down any life in its way.\"\nDrop:\nGul'dan (Mythic)\nZone:\nThe Nighthold" }
entries[137576] = { ["name"] = "Dim Coldflame Core", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a rideable Coldflame Infernal.\nSummons and dismisses your Coldflame Infernal.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The strange icy flames cause you to sweat and shiver at the same time.\"\nTrading Post" }
entries[137577] = { ["name"] = "Predatory Bloodgazer", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Predatory Bloodgazer .\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The sheer amount of raw red berries these fierce omnivores consume gives them their distinctive eye color.\"\nQuest:\nBloodgazer Reunion" }
entries[137578] = { ["name"] = "Snowfeather Hunter", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Snowfeather Hunter .\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Capable of hiding in a fog bank until prey approaches, then slicing them open with one claw-raised jump.\"\nQuest:\nSnowfeather Reunion" }
entries[137579] = { ["name"] = "Brilliant Direbeak", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Brilliant Direbeak .\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The shimmering hides of these deceptively fierce and coordinated beasts are intended to confuse and disorient prey.\"\nQuest:\nDirebeak Reunion" }
entries[137580] = { ["name"] = "Viridian Sharptalon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Viridian Sharptalon .\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Adept at blending into dense, magical forests, such as one may find around the Broken Isles.\"\nQuest:\nSharptalon Reunion" }
entries[137582] = { ["name"] = "Ashbringer", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Sword\n9 - 17 Damage Speed 3.60\n(3.6 damage per second)\n+5 Strength\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\n\nHoly Artifact Relic Slot\nFire Artifact Relic Slot\nUse: Lash out with the Ashbringer , dealing (174.3% of Attack Power)% Radiant damage to all enemies within 12 yd in front of you, and reducing movement speed by 50% for 6 sec.\n\nDemon and Undead enemies are stunned for 6 sec if struck by the Wake of Ashes.\n\"Blade of the Scarlet Highlord\"" }
entries[137589] = { ["name"] = "Empyrean Society Uniform", ["text"] = "Quest Item\nUse: Fools cultists into thinking that you are a recruit of the Empyrean Society. Only works on cultists in the Empyrean Society Enclave in Azsuna.\n\"Embroidered with the insignia of the Empyrean Society cult.\"" }
