entries[137604] = { ["name"] = "Unstable Riftstone", ["text"] = "Binds when picked up\nDuration: 1 day (real time)\nUse: Shatter the stone, inflicting 25 damage per sec. over 6 sec on up to 3 enemies within 5 yards. (1 Min Cooldown)\n\"Shifting quickly between this reality and another.\"" }
entries[137605] = { ["name"] = "Plans: Leystone Boots", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to make Leystone Boots.\nGreatly reduces the materials required to craft Leystone Boots.\nRequires Legion Blacksmithing (1)\n\nLeystone Boots\nBinds when equipped\nFeet Plate\n11 Armor\n+4 [Strength or Intellect]\n+5 Stamina\nDurability 65 / 65\nSell Price:\nRequires Leystone Ore (12), Foxflower Flux (2)\nOptional Reagents: Optional Reagent Slot (#48)" }
entries[137606] = { ["name"] = "Plans: Leystone Gauntlets", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to make Leystone Gauntlets.\nGreatly reduces the materials required to craft Leystone Gauntlets.\nRequires Legion Blacksmithing (1)\n\nLeystone Gauntlets\nBinds when equipped\nHands Plate\n10 Armor\n+4 [Strength or Intellect]\n+6 Stamina\nDurability 50 / 50\nSell Price:\nRequires Leystone Ore (12), Foxflower Flux (3)\nOptional Reagents: Optional Reagent Slot (#48)" }
entries[137607] = { ["name"] = "Plans: Leystone Helm", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to make a Leystone Helm.\nGreatly reduces the materials required to craft a Leystone Helm.\nRequires Legion Blacksmithing (1)\n\nLeystone Helm\nBinds when equipped\nHead Plate\n13 Armor\n+5 [Strength or Intellect]\n+7 Stamina\nDurability 85 / 85\nSell Price:\nRequires Leystone Ore (16), Foxflower Flux\nOptional Reagents: Optional Reagent Slot (#49)" }
entries[137608] = { ["name"] = "Growling Sac", ["text"] = "Binds when picked up\n\"It seems like there's something moving around inside...\"\n<Right Click to Open>" }
entries[137609] = { ["name"] = "Wood", ["text"] = "Binds when picked up\n\"Dried logs of timber that will easily burn.\"" }
