entries[137612] = { ["name"] = "Raw Meat", ["text"] = "Binds when picked up\nUse: Consumption of undercooked meat may cause illness.\n\"Marbled with fat, this choice cut of meat might make a great steak if cooked properly.\"" }
entries[137613] = { ["name"] = "Hearty Steak", ["text"] = "Binds when picked up\nUse: Provides ample sustenance when consumed.\n\"Seared to perfection, this steak should provide ample sustenance.\"" }
entries[137614] = { ["name"] = "Biting Frostshard Core", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a rideable Frostshard Infernal.\nSummons and dismisses your Frostshard Infernal.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These icy minions come from an unknown plane far from this one.\"\nAchievement:\nNo Stable Big Enough\nCategory:\nMounts" }
entries[137615] = { ["name"] = "Molten Flarecore", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a rideable Flarecore Infernal.\nSummons and dismisses your Flarecore Infernal .\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The Legion has conquered thousands of other planets, devising fiendish alterations to their war machines when faced with extreme conditions.\"\nTrading Post" }
entries[137616] = { ["name"] = "Emalon's Charged Core", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Mail\n12 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 4 Critical Strike\n+ 6 Mastery\nDurability 200 / 200\nClasses: Shaman\nEquip: If Crash Lightning hits 3 or more targets, you deal 10% increased damage for 10 sec.\n\"Deep within the vault protected by Wintergrasp, Emalon the Storm Watcher stood guard with deadly determination.\"\nSell Price:" }
entries[137617] = { ["name"] = "Researcher's Notes", ["text"] = "Quest Item\n\"A tightly bound scroll of handwritten notes.\"" }
entries[137618] = { ["name"] = "Mountain Berries", ["text"] = "Binds when picked up\nUse: Provides minimal sustenance when consumed.\n\"Colorful fruit from the Highmountain region that provides minimal sustenance.\"" }
entries[137620] = { ["name"] = "Neqistia Seed Pods", ["text"] = "Quest Item\nUse: Spit a mouthful of water" }
entries[137621] = { ["name"] = "Grimoire of Damnation", ["text"] = "Quest Item\n\"The journal of the Archlich Kel'Thuzad, written during his time in Naxxramas.\"" }
entries[137622] = { ["name"] = "Imp in a Jar", ["text"] = "Binds when picked up\nUnique\nDuration: 1 day (real time)\nUse: Free the trapped imp. He promises his loyalty!\n\"It looks a little cramped in there.\"" }
entries[137623] = { ["name"] = "Amulet of Command", ["text"] = "Binds when picked up\nUnique\nDuration: 1 day (real time)\nUse: Raise the Amulet of Command, binding a Demon to your will temporarily." }
