entries[137627] = { ["name"] = "Immaculate Battle-Stone", ["text"] = "Use: Instantly upgrades any battle pet to Epic quality.\nSell Price:" }
entries[137628] = { ["name"] = "Smooth Sunrunner Hide", ["text"] = "Quest Item\n\"Soft to the touch, yet incredibly durable.\"" }
entries[137636] = { ["name"] = "First-Run Armament", ["text"] = "\"While it was the best in its day, it hasn't endured.\"\nSell Price:" }
entries[137637] = { ["name"] = "Fracturing Arms", ["text"] = "\"Left in storage for too long, these arms would not survive battle.\"\nSell Price:" }
entries[137638] = { ["name"] = "Fel-Corrupted Uniform", ["text"] = "\"This uniform appears to have been left too close to a fel energy source and should no longer be worn.\"\nSell Price:" }
entries[137639] = { ["name"] = "Frost Tempered Arms", ["text"] = "\"After sitting in such extreme cold, these weapons became extremely brittle when exposed to warmer battlefields.\"\nSell Price:" }
entries[137640] = { ["name"] = "Mildew Saturated Armaments", ["text"] = "\"After prolonged exposure to the balmy and humid weather, these armaments are slimy and tattered with mildew.\"\nSell Price:" }
entries[137641] = { ["name"] = "Rusting Arms", ["text"] = "\"Local Iron Horde metals have proven not to be a lasting weapon material.\"\nSell Price:" }
entries[137642] = { ["name"] = "Mark of Honor", ["text"] = "Binds to Warband\n\"Exchanged for legacy weapons and armor at Player vs. Player vendors.\"\nSell Price:" }
entries[137643] = { ["name"] = "Old Scythe", ["text"] = "\"It looks as if it was part of a pair, but the good one is missing.\"\nSell Price:" }
entries[137644] = { ["name"] = "Decaying Heart", ["text"] = "\"Doesn't look like a bear heart. Where did this one come from?\"\nSell Price:" }
entries[137648] = { ["name"] = "Nimble Brew", ["text"] = "Conjured Item\nUnique: Nimble Brew (2)\nUse: Removes all root, stun, fear and horror effects and reduces the duration of future such effects by 60% for 6 sec. (5 Min Cooldown)" }
entries[137649] = { ["name"] = "Hammer of Khaz'goroth", ["text"] = "Quest Item\nUnique\n\"The Hammer of Khaz'goroth is no longer in the hands of Dargrul the Underking. Take it to Aegwynn's Chamber in Dalaran.\"" }
